/** clicks per code per minute */
function perMinute(events) {
  // Write your solution here
  const out = {};
  for (const e of events) {
    out[e.code] = out[e.code] || [];
    out[e.code].push({ minute: Math.round(e.at / 60000) * 60000, count: 1 });
  }
  return out;
}

